function setup() {
  createCanvas(640, 640);
  noStroke();
}

function draw() {
  background(42, 47, 66);
  translate(width/2, height/2);

  for (let j = 0; j <= 360; j+=30) {
    let jx = sin(radians(j))*120;
    let jy = cos(radians(j))*120;
    push();
    translate(jx, jy);
    rotate(radians(-j+frameCount));
    for (let q = 8; q > 1; q--) {
      let s = q*7;
      beginShape();
      fill(map(q, 8, 1, 198, 243), map(q, 8, 1, 212, 64), map(q, 8, 1, 67, 73));
      for (let i = 0; i < 360; i++) {
        let x = pow(sin(radians(i)), 7)*(s/2);
        let y = cos(radians(i))*(s*2.7);
        vertex(x, y);
      }
      endShape(CLOSE);
    }
    pop();
  }
}
